/* =============================================================
   sourcemap-embed.jsx — renders the Source Map app in a shadow root
   ============================================================= */
import React from 'react';
import { createRoot } from 'react-dom/client';
import App from '../../vite/ParallelsOfTheGods.jsx';
// Compiled Tailwind + base CSS of the Source Map app (generated by build_combined.sh)
import appCss from 'sourcemap-css';

export function mountSourceMap(host) {
  const shadow = host.shadowRoot || host.attachShadow({ mode: 'open' });
  const style = document.createElement('style');
  style.textContent = appCss + `
    :host { display: block; }
    #sm-root { min-height: calc(100vh - var(--nav-h, 64px)); }
  `;
  const root = document.createElement('div');
  root.id = 'sm-root';
  shadow.append(style, root);
  createRoot(root).render(<App />);
}
